import{_ as t,c as o,o as e,ai as n}from"./chunks/framework.BrjRfu4a.js";const c=JSON.parse('{"title":"국채 발행근거 | 의의 및 제도변천 | 한국 국채","description":"국채법은 국채의 발행 및 상환에 관한 일반법으로서, 국채에 대한 기본적인 사항을 규정하고 있습니다. 특히 국채법 제3조는 국채 발행의 주체와 방식에 대해 명확히 하고 있습니다.","frontmatter":{"title":"국채 발행근거 | 의의 및 제도변천 | 한국 국채","description":"국채법은 국채의 발행 및 상환에 관한 일반법으로서, 국채에 대한 기본적인 사항을 규정하고 있습니다. 특히 국채법 제3조는 국채 발행의 주체와 방식에 대해 명확히 하고 있습니다.","head":[["meta",{"property":"og:title","content":"국채 발행근거 | 의의 및 제도변천 | 한국 국채"}],["meta",{"property":"og:description","content":"국채법은 국채의 발행 및 상환에 관한 일반법으로서, 국채에 대한 기본적인 사항을 규정하고 있습니다. 특히 국채법 제3조는 국채 발행의 주체와 방식에 대해 명확히 하고 있습니다."}],["meta",{"property":"og:image","content":"/images/RiskQuantHaun.png"}],["meta",{"property":"og:url","content":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/foundations-and-evolution/legal-basis"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/foundations-and-evolution/legal-basis"}],["link",{"rel":"alternate","hreflang":"en","href":"https://risk-quant-haun.github.io/korean-treasury-bonds/foundations-and-evolution/legal-basis"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/foundations-and-evolution/legal-basis"}],["link",{"rel":"canonical","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/foundations-and-evolution/legal-basis"}]],"date":"2025-03-02T00:00:00.000Z"},"headers":[],"relativePath":"ko/korean-treasury-bonds/foundations-and-evolution/legal-basis.md","filePath":"ko/korean-treasury-bonds/foundations-and-evolution/legal-basis.md"}'),i={name:"ko/korean-treasury-bonds/foundations-and-evolution/legal-basis.md"};function l(r,a,s,u,d,h){return e(),o("div",null,a[0]||(a[0]=[n('<h1 id="🏦-국채-발행근거" tabindex="-1">🏦 국채 발행근거 <a class="header-anchor" href="#🏦-국채-발행근거" aria-label="Permalink to &quot;🏦 국채 발행근거&quot;">​</a></h1><p><strong>의의 및 제도변천 | 한국 국채 | 2025.03.02</strong></p><h2 id="_1️⃣-국채-발행의-법적-기반" tabindex="-1">1️⃣ 국채 발행의 법적 기반 <a class="header-anchor" href="#_1️⃣-국채-발행의-법적-기반" aria-label="Permalink to &quot;1️⃣ 국채 발행의 법적 기반&quot;">​</a></h2><p>대한민국 정부는 건전재정 유지를 위해 명확한 법적 근거를 바탕으로 국채를 발행하고 있습니다. 국채 발행의 법적 체계는 헌법을 최상위로 하여 국가재정법, 국채법 등으로 구성되어 있으며, 이를 통해 체계적이고 투명한 국채 발행 시스템을 유지하고 있습니다.</p><h2 id="_2️⃣-헌법상-국채-발행-근거" tabindex="-1">2️⃣ 헌법상 국채 발행 근거 <a class="header-anchor" href="#_2️⃣-헌법상-국채-발행-근거" aria-label="Permalink to &quot;2️⃣ 헌법상 국채 발행 근거&quot;">​</a></h2><p>대한민국 헌법 제58조는 국채 발행의 기본원칙을 다음과 같이 명시하고 있습니다:</p><div class="tip custom-block"><p class="custom-block-title">헌법상 국채 발행 근거</p><ul><li>&quot;국채를 모집하거나 예산외에 국가의 부담이 될 계약을 체결하려 할 때에는 정부는 미리 국회의 의결을 얻어야 한다&quot;</li></ul></div><p>이는 국채 발행이 국가의 중요한 재정 활동으로서 국회의 통제를 받아야 함을 명확히 하고 있습니다.</p><h2 id="_3️⃣-국가재정법상-국채-발행-근거" tabindex="-1">3️⃣ 국가재정법상 국채 발행 근거 <a class="header-anchor" href="#_3️⃣-국가재정법상-국채-발행-근거" aria-label="Permalink to &quot;3️⃣ 국가재정법상 국채 발행 근거&quot;">​</a></h2><p>국가재정법은 국가 재정운용의 기본법으로서 국채 발행에 대한 더 구체적인 근거를 제공합니다:</p><div class="warning custom-block"><p class="custom-block-title">국가재정법상 국채 발행 근거</p><ul><li><strong>제18조</strong>: &quot;국가의 세출은 국채·차입금 외의 세입을 그 재원으로 한다. 다만, 부득이한 경우에는 국회의 의결을 얻은 금액의 범위 안에서 국채 또는 차입금으로써 충당할 수 있다&quot;</li><li><strong>제20조</strong>: &quot;정부는 기존 국채를 새로운 국채로 대체하기 위하여 필요한 경우에는 제1항 제1호의 한도액을 초과하여 국채를 발행할 수 있다. 이 경우 미리 국회에 이를 보고하여야 한다&quot;</li></ul></div><p>이러한 조항들은 국채 발행이 원칙적으로 제한되지만, 국회의 승인을 받은 경우 가능하다는 원칙을 확립하고 있습니다.</p><h2 id="_4️⃣-국채법상-국채-발행-근거" tabindex="-1">4️⃣ 국채법상 국채 발행 근거 <a class="header-anchor" href="#_4️⃣-국채법상-국채-발행-근거" aria-label="Permalink to &quot;4️⃣ 국채법상 국채 발행 근거&quot;">​</a></h2><p>국채법은 국채의 발행 및 상환에 관한 일반법으로서, 국채에 대한 기본적인 사항을 규정하고 있습니다. 특히 국채법 제3조는 국채 발행의 주체와 방식에 대해 명확히 하고 있습니다:</p><div class="danger custom-block"><p class="custom-block-title">국채법상 국채 발행 근거</p><ul><li>&quot;국채는 공공자금관리기금의 부담으로 기획재정부장관이 발행하되 다른 법률에 특별한 규정이 있는 경우에는 그 법률에 따라 발행할 수 있다&quot;</li></ul></div><p>이 조항은 국채 발행의 기본원칙을 법률로써 엄격하게 규정하고 있습니다.</p><h2 id="_5️⃣-국고채-관련-세부-규정" tabindex="-1">5️⃣ 국고채 관련 세부 규정 <a class="header-anchor" href="#_5️⃣-국고채-관련-세부-규정" aria-label="Permalink to &quot;5️⃣ 국고채 관련 세부 규정&quot;">​</a></h2><p>국고채와 관련된 더 세부적인 사항들은 다음과 같은 규정들에서 정하고 있습니다:</p><ul><li>「국고채권의 발행 및 국고채전문딜러 운영에 관한 규정」(기획재정부 고시): 국고채 관련 입찰방식, 국고채전문딜러, 조기상환, 교환 등 세부사항 규정</li><li>한국은행의 「국채사무취급절차」: 국채 발행, 상환 등과 관련된 실무적 절차 규정</li></ul><h2 id="_6️⃣-법적-기반의-의의" tabindex="-1">6️⃣ 법적 기반의 의의 <a class="header-anchor" href="#_6️⃣-법적-기반의-의의" aria-label="Permalink to &quot;6️⃣ 법적 기반의 의의&quot;">​</a></h2><p>이와 같은 명확한 법적 근거를 바탕으로 한 국채 발행은 국가 재정의 투명성과 책임성을 높이는 중요한 요소입니다. 특히 국회의 통제를 받는 국채 발행 체계는 재정 민주주의의 실현이라는 측면에서도 큰 의미를 가집니다.</p>',21)]))}const b=t(i,[["render",l]]);export{c as __pageData,b as default};
